import math
def check(x):
    if x<=0:
        return False
    y = int(math.sqrt(x))
    if y*y==x:
        return True
    return False
t = int(input())
for ii in range(0,t):
    n = int(input())
    fl = 0
    for i in range(1,n+1):
        j = n-i*i
        if check(j):
            fl=1
            break
    if fl==1:
        print("Yes")
    else:
        print("No")
